 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    sources = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 2]
    if not sources:
        return g
    sr, sc = sources[0]
    row_scores = [sum(v == 8 for v in row) for row in g]
    col_scores = [sum(g[r][c] == 8 for r in range(h)) for c in range(w)]
    horizontal_walls = max(row_scores, default=0) >= max(col_scores, default=0)

    if horizontal_walls:
        # Horizontal 8-bars; the signal advances vertically and turns
        # sideways along the open row immediately before each bar.
        axis_len, transverse_len = h, w
        source_axis, source_transverse = sr, sc
        sign = 1 if sr <= (h - 1) / 2 else -1
        walls = [i for i, score in enumerate(row_scores)
                 if score >= max(3, (w + 1) // 2) and (i - sr) * sign > 0]
        walls.sort(reverse=(sign < 0))
        active = {source_transverse}
        previous = source_axis
        for wall in walls:
            # Continue each vertical track up to the bar.
            for p in active:
                for a in range(previous + sign, wall, sign):
                    if g[a][p] == 0:
                        g[a][p] = 2
            before = wall - sign
            holes = [q for q, v in enumerate(g[wall]) if v == 0]
            reached = set()
            for p in active:
                if p in holes:
                    g[wall][p] = 2
                    reached.add(p)
                    continue
                for lateral in (-1, 1):
                    candidates = [q for q in holes if (q - p) * lateral > 0]
                    q = (min(candidates, key=lambda x: abs(x-p)) if candidates
                         else (0 if lateral < 0 else w - 1))
                    step = 1 if q >= p else -1
                    for x in range(p, q + step, step):
                        if g[before][x] == 0:
                            g[before][x] = 2
                    if q in holes:
                        g[wall][q] = 2
                        reached.add(q)
            active = reached
            previous = wall
            if not active:
                break
        for p in active:
            for a in range(previous + sign, axis_len if sign > 0 else -1, sign):
                if g[a][p] == 0:
                    g[a][p] = 2
    else:
        # Vertical 8-bars; transpose the same ray-turning construction.
        axis_len, transverse_len = w, h
        source_axis, source_transverse = sc, sr
        sign = 1 if sc <= (w - 1) / 2 else -1
        walls = [i for i, score in enumerate(col_scores)
                 if score >= max(3, (h + 1) // 2) and (i - sc) * sign > 0]
        walls.sort(reverse=(sign < 0))
        active = {source_transverse}
        previous = source_axis
        for wall in walls:
            for p in active:
                for a in range(previous + sign, wall, sign):
                    if g[p][a] == 0:
                        g[p][a] = 2
            before = wall - sign
            holes = [q for q in range(h) if g[q][wall] == 0]
            reached = set()
            for p in active:
                if p in holes:
                    g[p][wall] = 2
                    reached.add(p)
                    continue
                for lateral in (-1, 1):
                    candidates = [q for q in holes if (q - p) * lateral > 0]
                    q = (min(candidates, key=lambda x: abs(x-p)) if candidates
                         else (0 if lateral < 0 else h - 1))
                    step = 1 if q >= p else -1
                    for x in range(p, q + step, step):
                        if g[x][before] == 0:
                            g[x][before] = 2
                    if q in holes:
                        g[q][wall] = 2
                        reached.add(q)
            active = reached
            previous = wall
            if not active:
                break
        for p in active:
            for a in range(previous + sign, axis_len if sign > 0 else -1, sign):
                if g[p][a] == 0:
                    g[p][a] = 2
    return g
